/**
 * RBQ-Draw-Plugins Sub-Plugin: 摸鱼悬浮球 (Slack-off Floating Ball)
 * Version: 1.0.1
 * Author: TTWP-09
 * Description: 将生图插件的悬浮球样式替换为超可爱的摸鱼猫咪图标，并带有精致的悬停微动画。
 */
(function() {
    'use strict';

    // Inject CSS styles automatically
    const styleId = 'rbq-sdt-custom-float-style';
    if (!document.getElementById(styleId)) {
        const style = document.createElement('style');
        style.id = styleId;
        style.innerHTML = `
            #st-scene-trigger-floating-toggle {
                background: #ffffff !important;
                border: 2.5px solid #ff9ebb !important;
                border-radius: 50% !important;
                box-shadow: 0 4px 14px rgba(255, 158, 187, 0.45) !important;
                overflow: hidden !important;
                display: flex !important;
                align-items: center !important;
                justify-content: center !important;
                transition: transform 0.25s cubic-bezier(0.175, 0.885, 0.32, 1.275), box-shadow 0.25s ease !important;
            }
            #st-scene-trigger-floating-toggle:hover {
                transform: translateY(-50%) scale(1.12) rotate(4deg) !important;
                box-shadow: 0 6px 20px rgba(255, 158, 187, 0.65) !important;
                border-color: #ff7aa8 !important;
            }
            #st-scene-trigger-floating-toggle:active {
                transform: translateY(-50%) scale(0.92) !important;
                box-shadow: 0 2px 8px rgba(255, 158, 187, 0.3) !important;
            }
            #st-scene-trigger-floating-toggle .st-scene-trigger-kite-icon {
                display: none !important;
            }
            #st-scene-trigger-floating-toggle::after {
                content: "";
                display: block;
                width: 82%;
                height: 82%;
                background-image: url("data:image/jpeg;base64,");
                background-size: contain;
                background-position: center;
                background-repeat: no-repeat;
            }
        `;
        document.head.appendChild(style);
        console.info('[RBQ Plugin] Slack-off Floating Ball (摸鱼悬浮球) styles loaded.');
    }
})();
